class Solution:
    def pathSum(self, root, targetSum):
        ans=[]; path=[]
        def dfs(node, rem):
            if not node: return
            path.append(node.val); rem -= node.val
            if not node.left and not node.right and rem == 0: ans.append(path[:])
            dfs(node.left, rem); dfs(node.right, rem)
            path.pop()
        dfs(root, targetSum)
        return ans

